code:
АдресAPI = ЭтотОбъект.АдресGitAPI;
Репозиторий = ЭтотОбъект.РепозиторийGit;
Ветка = ЭтотОбъект.ВеткаGit;
Токен = ЭтотОбъект.ТокенGit;
Каталог = ЭтотОбъект.КаталогБазыЗнанийGit;

Результат = "";

Заголовки = Новый Соответствие;
Заголовки.Вставить("Authorization", "token " + Токен);
Заголовки.Вставить("User-Agent", "1C-Enterprise");
Заголовки.Вставить("Accept", "application/vnd.github.v3+json");

Если Найти(АдресAPI, "https://") > 0 Тогда
    АдресБезСхемы = СтрЗаменить(АдресAPI, "https://", "");
    ИспользоватьSSL = Истина;
    Порт = 443;
Иначе
    АдресБезСхемы = СтрЗаменить(АдресAPI, "http://", "");
    ИспользоватьSSL = Ложь;
    Порт = 80;
КонецЕсли;

ПозицияДвоеточия = Найти(АдресБезСхемы, ":");
Если ПозицияДвоеточия > 0 Тогда
    Хост = Лев(АдресБезСхемы, ПозицияДвоеточия - 1);
    Порт = Число(Сред(АдресБезСхемы, ПозицияДвоеточия + 1));
Иначе
    ПозицияСлеша = Найти(АдресБезСхемы, "/");
    Если ПозицияСлеша > 0 Тогда
        Хост = Лев(АдресБезСхемы, ПозицияСлеша - 1);
    Иначе
        Хост = АдресБезСхемы;
    КонецЕсли;
КонецЕсли;

Если ИспользоватьSSL Тогда
    SSL = Новый ЗащищенноеСоединениеOpenSSL();
Иначе
    SSL = Неопределено;
КонецЕсли;

Соединение = Новый HTTPСоединение(Хост, Порт, , , , 30, SSL);

URLПолучения = "/repos/" + Репозиторий + "/contents/" + Каталог + "?ref=" + Ветка;
ЗапросПолучения = Новый HTTPЗапрос(URLПолучения, Заголовки);

Попытка
    ОтветПолучения = Соединение.Получить(ЗапросПолучения);

    Если ОтветПолучения.КодСостояния = 200 Тогда
        ТелоОтвета = ОтветПолучения.ПолучитьТелоКакСтроку();
        ЧтениеJSON = Новый ЧтениеJSON;
        ЧтениеJSON.ОткрытьСтроку(ТелоОтвета);
        МассивФайлов = ПрочитатьJSON(ЧтениеJSON, Ложь);
        ЧтениеJSON.Закрыть();

        КоличествоУдалено = 0;
        ОшибкиУдаления = "";

        Если ТипЗнч(МассивФайлов) = Тип("Массив") Тогда
            Для Каждого Файл Из МассивФайлов Цикл
                ИмяФайла = Файл["name"];
                SHAФайла = Файл["sha"];
                ПутьФайла = Файл["path"];

                ЗаписьJSON = Новый ЗаписьJSON;
                ЗаписьJSON.УстановитьСтроку();
                ЗаписатьJSON(ЗаписьJSON, Новый Структура("message,sha,branch", 
                    "Очистка базы знаний: удаление " + ИмяФайла, SHAФайла, Ветка));
                ТелоУдаления = ЗаписьJSON.Закрыть();

                URLУдаления = "/repos/" + Репозиторий + "/contents/" + ПутьФайла;
                ЗапросУдаления = Новый HTTPЗапрос(URLУдаления, Заголовки);
                ЗапросУдаления.УстановитьТелоИзСтроки(ТелоУдаления);

                Попытка
                    ОтветУдаления = Соединение.Удалить(ЗапросУдаления);
                    Если ОтветУдаления.КодСостояния = 200 Тогда
                        КоличествоУдалено = КоличествоУдалено + 1;
                    Иначе
                        ОшибкиУдаления = ОшибкиУдаления + ИмяФайла + "(код:" + ОтветУдаления.КодСостояния + "); ";
                    КонецЕсли;
                Исключение
                    ОшибкиУдаления = ОшибкиУдаления + ИмяФайла + "(ошибка:" + ОписаниеОшибки() + "); ";
                КонецПопытки;
            КонецЦикла;
        КонецЕсли;

        СодержимоеREADME = "# База знаний ИИ-агента 1С" + Символы.ПС + Символы.ПС 
            + "Каталог очищен " + Формат(ТекущаяДата(), "ДФ='yyyy-MM-dd HH:mm:ss'");
        Base64Содержимое = Base64Строка(ПолучитьДвоичныеДанныеИзСтроки(СодержимоеREADME, "UTF-8"));

        ЗаписьJSONReadme = Новый ЗаписьJSON;
        ЗаписьJSONReadme.УстановитьСтроку();
        ЗаписатьJSON(ЗаписьJSONReadme, Новый Структура("message,content,branch", 
            "Создание заглушки базы знаний", Base64Содержимое, Ветка));
        ТелоReadme = ЗаписьJSONReadme.Закрыть();

        URLReadme = "/repos/" + Репозиторий + "/contents/" + Каталог + "/_readme.md";
        ЗапросReadme = Новый HTTPЗапрос(URLReadme, Заголовки);
        ЗапросReadme.УстановитьТелоИзСтроки(ТелоReadme);

        Попытка
            ОтветReadme = Соединение.Записать(ЗапросReadme);
            ReadmeСоздан = (ОтветReadme.КодСостояния = 201);
        Исключение
            ReadmeСоздан = Ложь;
        КонецПопытки;

        Результат = "✅ База знаний очищена." + Символы.ПС 
            + "Удалено файлов: " + КоличествоУдалено + " из " + МассивФайлов.Количество();

        Если ОшибкиУдаления <> "" Тогда
            Результат = Результат + Символы.ПС + "⚠️ Ошибки: " + ОшибкиУдаления;
        КонецЕсли;

        Если ReadmeСоздан Тогда
            Результат = Результат + Символы.ПС + "📄 Создан файл _readme.md";
        КонецЕсли;

    ИначеЕсли ОтветПолучения.КодСостояния = 404 Тогда
        Результат = "ℹ️ Каталог '" + Каталог + "' не найден или уже пуст.";
    Иначе
        Результат = "❌ Ошибка: HTTP " + ОтветПолучения.КодСостояния 
            + Символы.ПС + ОтветПолучения.ПолучитьТелоКакСтроку();
    КонецЕсли;

Исключение
    Результат = "❌ Исключение: " + ОписаниеОшибки();
КонецПопытки;
